import { useMemo, useState } from 'react'
import { Search, SlidersHorizontal, X } from 'lucide-react'
import { GENRE_NAMES } from '../data/genres'
import type { Genre, SeriesStatus } from '../types'
import { SeriesCard } from '../components/SeriesCard'
import { Button } from '../components/ui'
import { navigate, useRoute } from '../lib/router'
import { useCatalog } from '../lib/catalog-context'
import { matchesSearch } from '../lib/selectors'
import { cx } from '../lib/utils'

type SortKey = 'trending' | 'popular' | 'rating' | 'newest' | 'latest' | 'title' | 'oldest'

const PAGE_SIZE = 60

const SORTS: { key: SortKey; label: string }[] = [
  { key: 'trending', label: 'Trending' },
  { key: 'popular', label: 'Most Popular' },
  { key: 'rating', label: 'Highest Rated' },
  { key: 'latest', label: 'Latest Released' },
  { key: 'newest', label: 'New Series' },
  { key: 'title', label: 'A → Z' },
  { key: 'oldest', label: 'Oldest First' },
]

const STATUSES: SeriesStatus[] = ['Ongoing', 'Completed', 'Hiatus']

export default function Catalog() {
  const route = useRoute()
  const { series: catalog, loading, source } = useCatalog()
  const urlSort = route.query.get('sort') as SortKey | null
  const [q, setQ] = useState('')
  const [genre, setGenre] = useState<Genre | 'All Genres'>('All Genres')
  const [status, setStatus] = useState<SeriesStatus | 'All Statuses'>('All Statuses')
  const [minRating, setMinRating] = useState(0)
  const [sort, setSort] = useState<SortKey>(urlSort && SORTS.some((s) => s.key === urlSort) ? urlSort : 'trending')
  const [filtersOpen, setFiltersOpen] = useState(false)
  // render in 60-card pages — mounting all ~2,100 cards at once made the
  // catalog page take 1-2s to appear on every visit
  const [shown, setShown] = useState(PAGE_SIZE)

  const results = useMemo(() => {
    let list = [...catalog]
    const query = q.trim().toLowerCase()
    if (query) list = list.filter((s) => matchesSearch(s, query))
    if (genre !== 'All Genres') list = list.filter((s) => s.genres.includes(genre))
    if (status !== 'All Statuses') list = list.filter((s) => s.status === status)
    if (minRating > 0) list = list.filter((s) => s.rating >= minRating)

    switch (sort) {
      case 'popular':
        list.sort((a, b) => b.views - a.views)
        break
      case 'rating':
        list.sort((a, b) => b.rating - a.rating || b.ratingCount - a.ratingCount)
        break
      case 'latest':
        list.sort((a, b) => +new Date(b.lastUpdated) - +new Date(a.lastUpdated))
        break
      case 'newest':
        list.sort((a, b) => +new Date(b.firstReleased) - +new Date(a.firstReleased))
        break
      case 'oldest':
        list.sort((a, b) => +new Date(a.firstReleased) - +new Date(b.firstReleased))
        break
      case 'title':
        list.sort((a, b) => a.title.localeCompare(b.title))
        break
      default:
        list.sort((a, b) => b.weeklyViews - a.weeklyViews)
    }
    return list
  }, [catalog, q, genre, status, minRating, sort])

  const activeFilters =
    (genre !== 'All Genres' ? 1 : 0) +
    (status !== 'All Statuses' ? 1 : 0) +
    (minRating > 0 ? 1 : 0)

  const clearAll = () => {
    setGenre('All Genres')
    setStatus('All Statuses')
    setMinRating(0)
    setQ('')
  }

  return (
    <main className="mx-auto max-w-[1240px] animate-fade-up px-4 py-10 sm:px-6 lg:px-8">
      {/* Header */}
      <div className="mb-8">
        <div className="eyebrow mb-2 text-accent">Discovery</div>
        <h1 className="text-3xl font-extrabold tracking-tight sm:text-4xl">Browse Catalogue</h1>
        <p className="mt-2 max-w-xl text-ink-soft">
          {source === 'mangadex'
            ? 'Live catalog of manhwa — every title has real chapter pages.'
            : source === 'anilist'
              ? 'Live catalog of the most popular manhwa on AniList — search by series title, author, or artist.'
              : 'Search by series title, author, or artist.'}
        </p>
      </div>

      {/* Search + sort bar */}
      <div className="mb-6 flex flex-wrap items-center gap-3">
        <div className="flex h-11 min-w-[240px] flex-1 items-center gap-2.5 rounded-full border border-line-strong bg-paper px-4 focus-within:border-ink">
          <Search width={17} height={17} className="text-ink-faint" />
          <input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search series title, author, artist…"
            className="w-full bg-transparent text-sm outline-none placeholder:text-ink-faint"
          />
          {q && (
            <button onClick={() => setQ('')} aria-label="Clear Search" className="text-ink-faint hover:text-ink">
              <X width={15} height={15} />
            </button>
          )}
        </div>

        <div className="flex h-11 items-center gap-2 rounded-full border border-line-strong bg-paper px-4">
          <span className="text-xs font-semibold uppercase tracking-wide text-ink-faint">Sort</span>
          <select
            value={sort}
            onChange={(e) => setSort(e.target.value as SortKey)}
            className="bg-transparent text-sm font-semibold outline-none"
          >
            {SORTS.map((s) => (
              <option key={s.key} value={s.key}>
                {s.label}
              </option>
            ))}
          </select>
        </div>

        <button
          onClick={() => setFiltersOpen((v) => !v)}
          className={cx(
            'inline-flex h-11 items-center gap-2 rounded-full border px-4 text-sm font-semibold transition-colors',
            activeFilters > 0 || filtersOpen
              ? 'border-ink bg-ink text-paper'
              : 'border-line-strong bg-paper text-ink hover:border-ink',
          )}
        >
          <SlidersHorizontal width={16} height={16} />
          Filters {activeFilters > 0 && <span className="rounded-full bg-accent px-1.5 text-[10px] font-bold text-white">{activeFilters}</span>}
        </button>
      </div>

      {/* Filter panel */}
      {filtersOpen && (
        <div className="animate-fade-in mb-6 rounded-[18px] border border-line bg-paper-2/60 p-5">
          <div className="grid gap-6 md:grid-cols-3">
            {/* Genre */}
            <div>
              <div className="eyebrow mb-2.5 text-ink-faint">Genre</div>
              <div className="flex max-h-40 flex-wrap gap-1.5 overflow-y-auto thin-scroll pr-1">
                <FilterChip
                  label="All Genres"
                  active={genre === 'All Genres'}
                  onClick={() => setGenre('All Genres')}
                />
                {GENRE_NAMES.map((g) => (
                  <FilterChip
                    key={g}
                    label={g}
                    active={genre === g}
                    onClick={() => setGenre(genre === g ? 'All Genres' : g)}
                  />
                ))}
              </div>
            </div>

            {/* Status */}
            <div>
              <div className="eyebrow mb-2.5 text-ink-faint">Publishing Status</div>
              <div className="flex flex-wrap gap-1.5">
                <FilterChip
                  label="All Statuses"
                  active={status === 'All Statuses'}
                  onClick={() => setStatus('All Statuses')}
                />
                {STATUSES.map((s) => (
                  <FilterChip
                    key={s}
                    label={s}
                    active={status === s}
                    onClick={() => setStatus(status === s ? 'All Statuses' : s)}
                  />
                ))}
              </div>
              <div className="eyebrow mb-2.5 mt-5 text-ink-faint">Minimum Rating</div>
              <div className="flex flex-wrap gap-1.5">
                {[0, 3, 3.5, 4].map((r) => (
                  <FilterChip
                    key={r}
                    label={r === 0 ? 'Any' : `★ ${r}+`}
                    active={minRating === r}
                    onClick={() => setMinRating(r)}
                  />
                ))}
              </div>
            </div>

            {/* Quick links */}
            <div>
              <div className="eyebrow mb-2.5 text-ink-faint">Quick Views</div>
              <div className="flex flex-col gap-1.5">
                {[
                  { label: 'Find Completed Series', fn: () => { setStatus('Completed'); setSort('rating') } },
                  { label: 'New Series Debuts', fn: () => { setStatus('All Statuses'); setSort('newest') } },
                  { label: 'Find Ongoing Series', fn: () => { setStatus('Ongoing'); setSort('latest') } },
                ].map((l) => (
                  <button
                    key={l.label}
                    onClick={l.fn}
                    className="rounded-lg border border-line bg-paper px-3 py-2 text-left text-sm font-medium text-ink-soft transition-colors hover:border-ink hover:text-ink"
                  >
                    {l.label}
                  </button>
                ))}
              </div>
              {activeFilters > 0 && (
                <button
                  onClick={clearAll}
                  className="mt-4 text-sm font-semibold text-accent hover:underline"
                >
                  Clear All Filters
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Result count */}
      <div className="mb-5 text-sm text-ink-faint">
        {loading ? 'Loading live catalog…' : `${results.length} series found`}
        {genre !== 'All Genres' && ` in ${genre}`}
      </div>

      {/* Grid */}
      {loading ? (
        <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
          {Array.from({ length: 15 }).map((_, i) => (
            <div key={i}>
              <div className="aspect-[3/4] animate-pulse rounded-[14px] bg-paper-3/60" />
              <div className="mt-3 h-4 w-3/4 animate-pulse rounded bg-paper-3/60" />
              <div className="mt-2 h-3 w-1/2 animate-pulse rounded bg-paper-3/60" />
            </div>
          ))}
        </div>
      ) : results.length === 0 ? (
        <div className="rounded-[18px] border border-dashed border-line-strong bg-paper px-6 py-20 text-center">
          <div className="text-lg font-bold">No series match your filters</div>
          <p className="mx-auto mt-2 max-w-sm text-sm text-ink-soft">
            Try broadening your genre or rating selections to find more stories.
          </p>
          <div className="mt-5">
            <Button variant="outline" onClick={clearAll}>Clear All Filters</Button>
          </div>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
            {results.slice(0, shown).map((s) => (
              <SeriesCard key={s.id} series={s} />
            ))}
          </div>
          {shown < results.length && (
            <div className="mt-10 flex justify-center">
              <button
                onClick={() => setShown((n) => n + PAGE_SIZE)}
                className="rounded-full border border-line-strong bg-paper px-6 py-2.5 text-sm font-bold text-ink transition-colors hover:border-ink"
              >
                Show more ({results.length - shown} remaining)
              </button>
            </div>
          )}
        </>
      )}
    </main>
  )
}

function FilterChip({
  label,
  active,
  onClick,
}: {
  label: string
  active: boolean
  onClick: () => void
}) {
  return (
    <button
      onClick={onClick}
      className={cx(
        'rounded-full border px-3 py-1 text-xs font-medium transition-colors',
        active
          ? 'border-ink bg-ink text-paper'
          : 'border-line-strong bg-paper text-ink-soft hover:border-ink hover:text-ink',
      )}
    >
      {label}
    </button>
  )
}
